mapper.select:
SELECT e.id, e.corp_code, e.corp_name, e.corp_id, e.ding_user_id, e.employee_no, e.employee_name, e.department_id, e.department_name, e.mobile, e.status,
NULL AS permission_enabled, e.updated_at FROM ding_employee e LEFT JOIN ding_department d ON d.id = e.department_id
ORDER BY e.employee_no ASC, e.id ASC LIMIT #{pageSize} OFFSET #{offset}

mapper.sql:
WHERE d.status = 'ENABLED'
AND d.corp_code = #{corpCode}

    AND LOWER(d.department_name) LIKE CONCAT('%', LOWER(#{keyword}), '%')

